package com.bank.teller;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class StackQueueDemo {

    private static final Logger log = Logger.getLogger(StackQueueDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StackQueue requests = new StackQueue();

        requests.enqueue("REQ-SAV2001");   // Rajesh arrives first
        requests.enqueue("REQ-CUR3001");   // Priya arrives second
        requests.enqueue("REQ-SAV4002");   // third arrival

        log.info(() -> "peek (oldest) -> " + requests.peek());    // REQ-SAV2001
        log.info(() -> "serve -> " + requests.dequeue());         // REQ-SAV2001
        log.info(() -> "serve -> " + requests.dequeue());         // REQ-CUR3001

        requests.enqueue("REQ-CUR5003");   // arrives after some served
        log.info(() -> "serve -> " + requests.dequeue());         // REQ-SAV4002 (still FIFO)
        log.info(() -> "serve -> " + requests.dequeue());         // REQ-CUR5003
    }
}

