class StackQueue {

    private static final Logger log = Logger.getLogger(StackQueue.class.getName());

    private final Deque<String> input = new ArrayDeque<>();    // newest arrivals pushed here
    private final Deque<String> output = new ArrayDeque<>();   // oldest served from here

    // O(1): accept a new request.
    void enqueue(String ticket) {
        input.push(ticket);
        log.fine(() -> "enqueue " + ticket);
    }

    // Amortized O(1): serve the oldest request.
    String dequeue() {
        shiftIfNeeded();
        if (output.isEmpty()) {
            throw new IllegalStateException("no requests waiting");
        }
        String served = output.pop();
        log.fine(() -> "dequeue " + served);
        return served;
    }

    // Amortized O(1): look at the oldest request without serving.
    String peek() {
        shiftIfNeeded();
        if (output.isEmpty()) {
            throw new IllegalStateException("no requests waiting");
        }
        return output.peek();
    }

    // Transfer only when output is empty; reverses order so oldest is on top.
    private void shiftIfNeeded() {
        if (output.isEmpty()) {
            while (!input.isEmpty()) {
                output.push(input.pop());
            }
            log.fine("transferred input -> output (order reversed)");
        }
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
